+    const linkedTasks = tasks.filter((task) =>
+      matchesTaskPlan(task, plan.slugs[0] ? `@${plan.slugs[0]}` : `@${plan._ulid}`)
+    );
+
+    return {
+      _ulid: plan._ulid,
+      slugs: plan.slugs,
+      title: plan.title,
