+  for (const item of items) {
+    const summary = alignmentIndex.getImplementationSummary(item._ulid);
+    if (!summary) continue;
+    if (summary.linkedTasks.length > 0) {
+      specsWithTasks += 1;
+    } else {
+      orphanedSpecs += 1;
+    }
+    if (summary.isAligned) {
+      alignedSpecs += 1;
+    }
+  }
+
+  return {
