    85→  return tasks.map((task) => {
    86→    const exportedTask: ExportedTask = { ...task };
    87→
    88→    if (task.spec_ref) {
    89→      const title = resolveSpecRefTitle(task.spec_ref, items, refIndex);
    90→      if (title) {
    91→        exportedTask.spec_ref_title = title;
    92→      }
    93→    }
    94→
    95→    return exportedTask;
    96→  });
    97→}
    98→
    99→/**
   100→ * Get inherited ACs from traits for a spec item.
   101→ * AC: @gh-pages-export ac-4
   102→ */
   103→function getInheritedACs(
   104→  item: LoadedSpecItem,
   105→  traitIndex: TraitIndex
   106→): InheritedAC[] {
   107→  const inheritedAC = traitIndex.getInheritedAC(item._ulid);
   108→
   109→  return inheritedAC.map(({ trait, ac }) => ({
   110→    ...ac,
   111→    _inherited_from: `@${trait.slug}`,
   112→  }));
   113→}
   114→
   115→/**
   116→ * Expand items with inherited ACs from traits and test coverage.
   117→ * AC: @gh-pages-export ac-4
   118→ * AC: @web-dashboard ac-15 - Add test coverage for static mode
   119→ */
   120→function expandItems(
   121→  items: LoadedSpecItem[],
   122→  traitIndex: TraitIndex,
   123→  coveredACs: Set<string>
   124→): ExportedItem[] {
   125→  return items.map((item) => {
   126→    // Compute coverage for acceptance criteria using shared utility
   127→    const acWithCoverage =
   128→      item.acceptance_criteria && item.acceptance_criteria.length > 0
   129→        ? computeACCoverage(item, coveredACs)
   130→        : item.acceptance_criteria;
   131→
   132→    const exportedItem: ExportedItem = {
   133→      ...item,
   134→      acceptance_criteria: acWithCoverage,
   135→    };
   136→
   137→    // Get inherited ACs from traits
   138→    const inheritedACs = getInheritedACs(item, traitIndex);
   139→    if (inheritedACs.length > 0) {
   140→      exportedItem.inherited_acs = inheritedACs;
   141→    }
   142→
   143→    return exportedItem;
   144→  });
   145→}
   146→
   147→/**
   148→ * Convert validation result to exported format.
   149→ * AC: @gh-pages-export ac-5
   150→ */
   151→function convertValidationResult(
   152→  result: Awaited<ReturnType<typeof validate>>
   153→): ExportedValidation {
   154→  return {
   155→    valid: result.valid,
   156→    errorCount: result.schemaErrors.length + result.refErrors.length,
   157→    warningCount: result.orphans.length + result.completenessWarnings.length,
   158→    schemaErrors: result.schemaErrors,
   159→    refErrors: result.refErrors,
   160→    refWarnings: result.refWarnings,
   161→    orphans: result.orphans,
   162→    completenessWarnings: result.completenessWarnings,
   163→    traitCycles: result.traitCycleErrors,
   164→    errors: [
   165→      ...result.schemaErrors.map((e) => ({
   166→        file: e.file,
   167→        message: e.message,
   168→        path: e.path,
   169→      })),
   170→      ...result.refErrors.map((e) => ({
   171→        file: e.sourceFile || "unknown",
   172→        message: e.message,
   173→      })),
   174→    ],
   175→    warnings: [
   176→      ...result.orphans.map((o) => ({
   177→        file: "orphan",
   178→        message: `Orphaned ${o.type}: ${o.title}`,
   179→      })),
   180→      ...result.completenessWarnings.map((w) => ({
   181→        file: w.itemRef,
   182→        message: w.message,
   183→      })),
   184→    ],
   185→  };
   186→}
   187→
   188→function normalizeRef(ref: string | null | undefined): string | null {
   189→  if (!ref) return null;
   190→  return ref.startsWith("@") ? ref.slice(1) : ref;
   191→}
   192→
   193→function matchesTaskPlan(task: LoadedTask, planRef: string): boolean {
   194→  const normalizedPlanRef = normalizeRef(planRef);
   195→  const normalizedTaskPlan = normalizeRef(task.plan_ref);
   196→
   197→  if (!normalizedPlanRef || !normalizedTaskPlan) return false;
   198→  return (
   199→    normalizedTaskPlan === normalizedPlanRef ||
   200→    normalizedTaskPlan.toUpperCase().startsWith(normalizedPlanRef.toUpperCase())
   201→  );
   202→}
   203→
   204→function countTaskProgress(tasks: LoadedTask[]) {
   205→  return tasks.reduce(
   206→    (counts, task) => {
   207→      counts.total += 1;
   208→      switch (task.status) {
   209→        case "completed":
   210→          counts.completed += 1;
   211→          break;
   212→        case "in_progress":
   213→        case "pending_review":
   214→        case "needs_work":
   215→          counts.in_progress += 1;
   216→          break;
   217→        case "blocked":
   218→          counts.blocked += 1;
   219→          break;
   220→        default:
   221→          counts.pending += 1;
   222→          break;
   223→      }
   224→      return counts;
   225→    },
   226→    { total: 0, completed: 0, in_progress: 0, pending: 0, blocked: 0 }
   227→  );
   228→}
   229→
   230→function expandPlans(
   231→  plans: Awaited<ReturnType<typeof loadPlans>>,
   232→  tasks: LoadedTask[]
   233→) {
   234→  return plans.map((plan) => {
   235→    const linkedTasks = tasks.filter((task) =>
   236→      matchesTaskPlan(task, plan.slugs[0] ? `@${plan.slugs[0]}` : `@${plan._ulid}`)
   237→    );
   238→
   239→    return {
   240→      _ulid: plan._ulid,
   241→      slugs: plan.slugs,
   242→      title: plan.title,
   243→      status: plan.status,
   244→      created_at: plan.created_at,
   245→      approved_at: plan.approved_at ?? undefined,
   246→      completed_at: plan.completed_at ?? undefined,
   247→      derived_specs: plan.derived_specs,
   248→      derived_tasks: plan.derived_tasks,
   249→      spec_count: plan.derived_specs.length,
   250→      task_count: linkedTasks.length,
   251→      task_progress: countTaskProgress(linkedTasks),
   252→      content: plan.content,
   253→    };
   254→  });
   255→}
   256→
   257→function buildAlignmentResponse(tasks: LoadedTask[], items: LoadedSpecItem[], refIndex: ReferenceIndex) {
   258→  const alignmentIndex = new AlignmentIndex(tasks, items);
   259→  alignmentIndex.buildLinks(refIndex);
   260→
   261→  let specsWithTasks = 0;
   262→  let alignedSpecs = 0;
   263→  let orphanedSpecs = 0;
   264→
   265→  for (const item of items) {
   266→    const summary = alignmentIndex.getImplementationSummary(item._ulid);
   267→    if (!summary) continue;
   268→    if (summary.linkedTasks.length > 0) {
   269→      specsWithTasks += 1;
   270→    } else {
   271→      orphanedSpecs += 1;
   272→    }
   273→    if (summary.isAligned) {
   274→      alignedSpecs += 1;
   275→    }
   276→  }
   277→
   278→  return {
   279→    stats: {
   280→      totalSpecs: items.length,
   281→      specsWithTasks,
   282→      alignedSpecs,
   283→      orphanedSpecs,
   284→    },
   285→    warnings: alignmentIndex.findAlignmentWarnings(),
   286→  };
   287→}
   288→
   289→/**
   290→ * Generate a JSON snapshot of all kspec data.
   291→ * AC: @gh-pages-export ac-1, ac-2, ac-3, ac-4, ac-5
   292→ */
   293→export async function generateJsonSnapshot(
   294→  includeValidation = false
   295→): Promise<KspecSnapshot> {
   296→  const ctx = await initContext();
   297→
   298→  // Load all data
   299→  const tasks = await loadAllTasks(ctx);
   300→  const items = await loadAllItems(ctx);
   301→  const inboxItems = await loadInboxItems(ctx);
   302→  const metaContext = await loadMetaContext(ctx);
   303→  const plans = await loadPlans(ctx);
   304→  const sessionContext = await loadSessionContext(ctx);
   305→  const triageRecords = await loadTriageRecords(ctx);
   306→
   307→  // Build indexes
   308→  const { refIndex, traitIndex } = await buildIndexes(ctx);
   309→
   310→  // Scan test coverage for AC annotations
   311→  const coveredACs = await scanTestCoverage(ctx.rootDir);
   312→
   313→  // Expand tasks with resolved spec references
   314→  const exportedTasks = expandTasks(tasks, items, refIndex);
   315→
   316→  // Expand items with inherited ACs and test coverage
   317→  const exportedItems = expandItems(items, traitIndex, coveredACs);
   318→
   319→  // Build the snapshot
   320→  const snapshot: KspecSnapshot = {
   321→    version: await getKspecVersion(),
   322→    exported_at: new Date().toISOString(),
   323→    project: {
   324→      name: ctx.manifest?.project?.name || "Unknown Project",
   325→      version: ctx.manifest?.project?.version,
   326→    },
   327→    tasks: exportedTasks,
   328→    items: exportedItems,
   329→    inbox: inboxItems,
   330→    plans: expandPlans(plans, tasks),
   331→    triage: triageRecords,
   332→    session: sessionContext,
   333→    observations: metaContext.observations,
   334→    agents: metaContext.agents,
   335→    workflows: metaContext.workflows,
   336→    conventions: metaContext.conventions,
   337→  };
   338→
   339→  // Include validation if requested
   340→  if (includeValidation) {
   341→    const validationResult = await validate(ctx, {
   342→      schema: true,
   343→      refs: true,
   344→      orphans: true,
   345→      completeness: true,
   346→    });
   347→    snapshot.validation = convertValidationResult(validationResult);
   348→    snapshot.alignment = buildAlignmentResponse(tasks, items, refIndex);
   349→  } else {
   350→    snapshot.alignment = buildAlignmentResponse(tasks, items, refIndex);
   351→  }
   352→
   353→  return snapshot;
   354→}
   355→
   356→/**
   357→ * Calculate export statistics for dry-run.
   358→ * AC: @gh-pages-export ac-7
   359→ */
   360→export function calculateExportStats(snapshot: KspecSnapshot): ExportStats {
   361→  const jsonString = JSON.stringify(snapshot);
   362→
   363→  return {
   364→    taskCount: snapshot.tasks.length,
   365→    itemCount: snapshot.items.length,
   366→    inboxCount: snapshot.inbox.length,
   367→    planCount: snapshot.plans?.length ?? 0,
   368→    triageCount: snapshot.triage?.length ?? 0,
   369→    observationCount: snapshot.observations.length,
   370→    agentCount: snapshot.agents.length,
   371→    workflowCount: snapshot.workflows.length,
   372→    conventionCount: snapshot.conventions.length,
   373→    estimatedSizeBytes: Buffer.byteLength(jsonString, "utf-8"),
   374→  };
   375→}
   376→
   377→/**
   378→ * Format bytes to human-readable size.
   379→ */
   380→export function formatBytes(bytes: number): string {
   381→  if (bytes < 1024) return `${bytes} B`;
   382→  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
   383→  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
   384→}
   385→
